fn test_clause_v_untabled_directive_takes_the_generic_paths() {
	// SEQ: an inner directive outside the table renders as a note.
	seq_out := code.code_diagram('[?worker name="w" [?const [c 1]]]') or {
		assert false, 'render seq probe: ${err}'
		return
	}
	assert seq_out.contains('Note over w : [?const]'), 'untabled inner directive lost its generic note:\n${seq_out}'
	// CFG: an untabled directive composes into a basic block instead of
	// breaking it.
	cfg_out := code.code_diagram('[?const [c 1]]\n[?const [d 2]]') or {
		assert false, 'render cfg probe: ${err}'
		return
	}
	assert cfg_out.contains('flowchart TD'), 'expected a CFG for a code source:\n${cfg_out}'
	assert cfg_out.contains('b["[?const]\\n[?const]"]'), 'untabled directives did not compose into ONE basic block:\n${cfg_out}'
}

// ── clause (vi): the spec §10.2 tables ↔ the module's table ──────────
//
// The module's table drives the emitters, so deleting a row from it
// keeps the module SELF-consistent (the goldens catch the behavior
// change, but the completeness gate would not). The spec section is
// the independent side of the bidirectional check: §10.2's three
// tables and the module's rows must agree exactly, in both directions.

struct SpecRules {
mut:
	triggers []string
	breaks   []string
	seq      []string
}

fn spec_wave3_rules() SpecRules {
	spec_path := os.real_path(os.join_path(os.dir(@FILE), '..', '..', 'spec', '03-approved',
		'std-lib', 'diagram.md'))
	text := os.read_file(spec_path) or {
		assert false, 'read ${spec_path}: ${err}'
		return SpecRules{}
	}
	start := text.index('### §10.2 The sealed wave-3 rule table') or {
		assert false, '§10.2 heading not found in std-lib/diagram.md'
		return SpecRules{}
	}
	rest := text[start..]
	end := rest.index('### §10.3') or { rest.len }
	body := rest[..end]
	// Three labelled table blocks, each a run of `| … |` rows after its
	// bold caption. Directive cells carry `[?name]` tokens.
	mut out := SpecRules{}
	trig_at := body.index('**Sequence triggers**') or { 0 }
	brk_at := body.index('**Block breakers**') or { 0 }
	seq_at := body.index('**SEQ inner-dispatch classes**') or { 0 }
	erd_at := body.index('**ERD scalar types**') or { body.len }
	out.triggers = directive_tokens(body[trig_at..brk_at])
	out.breaks = directive_tokens(body[brk_at..seq_at])
	out.seq = directive_tokens(body[seq_at..erd_at])
	return out
}

fn directive_tokens(chunk string) []string {
	mut out := []string{}
	// Only the FIRST cell of a table row names directives; the Render /
	// Class cell is prose and may mention other directives.
	for line in chunk.split('\n') {
		if !line.starts_with('| `[?') {
			continue
		}
		cell := line[1..].all_before('|')
		mut i := 0
		for {
			j := cell.index_after('[?', i) or { break }
			mut k := j + 2
			for k < cell.len && ((cell[k] >= `a` && cell[k] <= `z`) || cell[k] == `-`) {
				k++
			}
			name := cell[j + 2..k]
			if name.len > 0 && name !in out {
				out << name
			}
			i = k
		}
	}
	return out
}

fn assert_set_equal(spec []string, module_ []string, what string) {
	mut missing_in_module := []string{}
	for d in spec {
		if d !in module_ {
			missing_in_module << d
		}
	}
	mut missing_in_spec := []string{}
	for d in module_ {
		if d !in spec {
			missing_in_spec << d
		}
	}
	assert missing_in_module.len == 0, '${what}: spec §10.2 rows with no module row: ${missing_in_module}'
	assert missing_in_spec.len == 0, '${what}: module rows with no spec §10.2 row: ${missing_in_spec}'
}

fn test_code_diagram_clause_vi_spec_tables_and_module_table_are_set_equal() {
	spec := spec_wave3_rules()
	t := code_rules()
	assert spec.triggers.len == 5, 'spec trigger rows: ${spec.triggers}'
	assert spec.breaks.len == 6, 'spec block-breaker rows: ${spec.breaks}'
	assert spec.seq.len >= 20, 'spec SEQ rows: ${spec.seq.len}'
	mut module_seq := []string{}
	for d, _ in t.seq {
		module_seq << d
	}
	assert_set_equal(spec.triggers, t.triggers, 'sequence triggers')
	assert_set_equal(spec.breaks, t.breaks, 'block breakers')
	assert_set_equal(spec.seq, module_seq, 'SEQ inner-dispatch classes')
}

// ── source: vcx/tests/diagram_completeness_gate_test.v ──
// diagram_completeness_gate_test.v — the DR-5 bidirectional
// completeness gate (#758, RULED 2026-08-20;
// ledger/rulings_2026_08_20_diagram_renderer.md). Normative statement:
// spec/03-approved/std-lib/diagram.md §completeness + code.md §10.1.2.
//
// Four clauses, red on synthetic drift in any direction:
//   (i)   the code.md §10.1.2 locked table's directive set and the
//         module's sealed rules rows are SET-EQUAL (both directions —
//         finding 6's one-way drift dies here),
//   (ii)  every rules row is exercised by the golden corpus — by its
//         own [?name in an embedded source, or by its EMITTER TWIN
//         (send/try-send, receive/try-receive, await family share one
//         emitter; the twin map is explicit below),
//   (iii) a synthetic registry directive OUTSIDE the table refuses
//         CXER0281 at top level (beside the corpus fixture
//         program-viz-021's [?secret], enforced by the round-trip
//         harness),
//   (iv)  the classification over the FULL grammar registry is total
//         and disjoint: every table name (row / alias / scaffold /
//         nested) is a live registry directive (a retired name — the
//         old `try` row — reddens here), the module's admission
//         verdict equals rows ∪ aliases ∪ scaffolding exactly, and the
//         nested-only emitters refuse at top level.

fn spec_table_directives() []string {
	spec_path := os.real_path(os.join_path(os.dir(@FILE), '..', '..', 'spec', '03-approved',
		'core', 'code.md'))
	text := os.read_file(spec_path) or {
		assert false, 'read ${spec_path}: ${err}'
		return []
	}
	// The §10.1.2 locked table: rows between the table header and the
	// next section heading; directive cells carry `[?name]` tokens.
	start := text.index('| Directive | Render |') or {
		assert false, '§10.1.2 table header not found in code.md'
		return []
	}
	rest := text[start..]
	end := rest.index('####') or { rest.len }
	table := rest[..end]
	mut out := []string{}
	mut i := 0
	for {
		j := table.index_after('[?', i) or { break }
		mut k := j + 2
		for k < table.len && ((table[k] >= `a` && table[k] <= `z`) || table[k] == `-`) {
			k++
		}
		name := table[j + 2..k]
		if name.len > 0 && name !in out {
			out << name
		}
		i = k
	}
	return out
}

struct RulesTable {
mut:
	rows     []string
	aliases  []string
	scaffold []string
	nested   []string
}

fn module_rules() RulesTable {
	val := code.diagram_rules_value() or {
		assert false, 'diagram_rules_value: ${err}'
		return RulesTable{}
	}
	mut t := RulesTable{}
	if val is cx.Element {
		for it in val.items {
			if it is cx.Element {
				mut dname := ''
				for a in it.attrs {
					if a.name == 'directive' {
						dname = cx.scalar_value_str_public(a.value)
					}
				}
				if dname == '' {
					continue
				}
				match it.name {
					'row' { t.rows << dname }
					'alias' { t.aliases << dname }
					'scaffold' { t.scaffold << dname }
					'nested' { t.nested << dname }
					else {}
				}
			}
		}
	}
	return t
}

fn test_clause_i_spec_table_and_module_rows_are_set_equal() {
	spec := spec_table_directives()
	t := module_rules()
	assert spec.len > 0
	assert t.rows.len > 0
	mut missing_in_module := []string{}
	for d in spec {
		if d !in t.rows {
			missing_in_module << d
		}
	}
	mut missing_in_spec := []string{}
	for d in t.rows {
		if d !in spec {
			missing_in_spec << d
		}
	}
	assert missing_in_module.len == 0, 'spec §10.1.2 rows with no module rule: ${missing_in_module}'
	assert missing_in_spec.len == 0, 'module rules with no spec §10.1.2 row: ${missing_in_spec}'
}

// Emitter twins: directives sharing ONE emitter with an exercised
// sibling (the rule text is per-directive; the emitter is shared).
const emitter_twins = {
	'try-send':    'send'
	'try-receive': 'receive'
	'await-all':   'await'
	'await-any':   'await'
	'await-race':  'await'
	'await':       'await-all'
}

fn test_clause_ii_every_rule_is_exercised_by_the_corpus() {
	dir := os.real_path(os.join_path(os.dir(@FILE), 'testdata', 'diagram_mermaid_golden'))
	mut files := os.ls(dir) or {
		assert false, 'golden dir missing'
		return
	}
	mut sources := []string{}
	for f in files {
		if !f.ends_with('.min.golden') {
			continue
		}
		g := os.read_file(os.join_path(dir, f)) or { continue }
		src := code.reverse_parse_diagram(g, 'mermaid') or { continue }
		sources << src
	}
	assert sources.len >= 40
	t := module_rules()
	mut unexercised := []string{}
	for d in t.rows {
		mut hit := false
		for s in sources {
			if s.contains('[?${d}') {
				hit = true
				break
			}
		}
		if !hit {
			if twin := emitter_twins[d] {
				for s in sources {
					if s.contains('[?${twin}') {
						hit = true
						break
					}
				}
			}
		}
		if !hit {
			unexercised << d
		}
	}
	assert unexercised.len == 0, 'rules rows with no exercising corpus source (nor emitter twin): ${unexercised}'
}

fn test_clause_iii_outside_table_directive_refuses_cxer0281() {
	// [?quote] is a live registry directive with NO render rule.
	src := '[?quote [x]]'
	if _ := code.render_diagram(src, 'mermaid') {
		assert false, 'expected CXER0281 for top-level [?quote]'
	} else {
		assert err.msg().contains('cx-err:CXER0281'), 'expected CXER0281, got: ${err.msg()}'
	}
}

fn test_clause_iv_registry_classification_is_total_and_disjoint() {
	t := module_rules()
	// Every table name is a LIVE registry directive (a retired name —
	// e.g. the deleted `try` entry — reddens here).
	mut stale := []string{}
	for d in t.rows {
		if !cx.is_directive_name(d) {
			stale << 'row:${d}'
		}
	}
	for d in t.aliases {
		if !cx.is_directive_name(d) {
			stale << 'alias:${d}'
		}
	}
	for d in t.scaffold {
		if !cx.is_directive_name(d) {
			stale << 'scaffold:${d}'
		}
	}
	for d in t.nested {
		if !cx.is_directive_name(d) {
			stale << 'nested:${d}'
		}
	}
	assert stale.len == 0, 'rules-table names not in the grammar registry: ${stale}'
	// Disjointness of the classes.
	for d in t.aliases {
		assert d !in t.rows, 'alias ${d} duplicates a row'
	}
	for d in t.scaffold {
		assert d !in t.rows, 'scaffold ${d} duplicates a row'
	}
	for d in t.nested {
		assert d !in t.rows, 'nested ${d} duplicates a row'
		assert d !in t.scaffold, 'nested ${d} duplicates scaffolding'
	}
	// The module's admission verdict is EXACTLY rows ∪ aliases ∪
	// scaffolding over the whole registry — every registry directive is
	// therefore exactly one of: admitted (row/alias/scaffold), nested
	// (emitter without top-level admission), or CXER0281-refused.
	for d in cx.directive_names {
		admitted := code.diagram_admitted(d) or {
			assert false, 'diagram_admitted(${d}): ${err}'
			return
		}
		expected := d in t.rows || d in t.aliases || d in t.scaffold
		assert admitted == expected, 'admission drift for [?${d}]: module says ${admitted}, table says ${expected}'
	}
	// The nested-only emitters refuse at top level.
	nested_sources := {
		'http-client': '[?http-client get="https://example.com/x"]'
		'fn':          '[?fn (\$x) \$x]'
	}
	for d, src in nested_sources {
		assert d in t.nested, '${d} expected in the nested class'
		if _ := code.render_diagram(src, 'mermaid') {
			assert false, 'expected CXER0281 for top-level [?${d}]'
		} else {
			assert err.msg().contains('cx-err:CXER0281'), '[?${d}]: expected CXER0281, got ${err.msg()}'
		}
	}
}

// ── source: vcx/tests/diagram_effect_completeness_gate_test.v ──
// diagram_effect_completeness_gate_test.v — the DR-5 bidirectional
// completeness gate for the THIRD renderable kind, the effect/capability
// graph (RULED: DGX-1b,
// ledger/rulings_2026_08_21_diagram_capabilities.md). Normative
// statement: spec/03-approved/std-lib/diagram.md §12.
//
// The subject is the module's sealed `[$diagram:effect-rules]` table —
// what is RENDERING POLICY. What is a FACT ABOUT THE ENGINE (the
// primitive→capability map) is deliberately NOT in that table: the
// module reads it live through `[$diagram-effect-table]`, because a
// stale copy could only ever fail by omitting a newly-gated effect
// point, and a capability diagram that quietly under-reports is worse
// than none. Clause (vii) is what holds that live read honest.
//
// Seven clauses, red on drift in either direction:
//
//   (i)   the roster rows are SET-EQUAL to the engine's
//         capability_names() — a capability added to the language and
//         not to this table reddens, and vice versa;
//   (ii)  every `dir` row names a LIVE §4.1 registry directive and a
//         capability in the roster;
//   (iii) every `arm` row's `under` names a live registry directive and
//         its carrier is a real image tag;
//   (iv)  every opacity class is produced by at least one source in the
//         golden corpus — a class that cannot be demonstrated is not a
//         class, and DGX-1c makes rendering them normative;
//   (v)   every roster capability is REACHED by at least one corpus
//         source, so no capability can lose its emitter silently;
//   (vi)  the tables in spec §12 and the module's `effect-rules` value
//         are SET-EQUAL in both directions — the clause that stays red
//         under a MATCHED deletion, because (i)-(v) go on agreeing with
//         themselves when the emitters read the table;
//   (vii) the module's live `effect-cap` verdict equals the engine's own
//         capability_gated_prims() map for every gated primitive.

struct EffectRules {
mut:
	caps  []string          // roster, in order
	flags map[string]string // capability → grant flag
	dirs  map[string]string // directive → capability
	arms  [][]string        // [carrier, under]
	opaqu []string          // opacity kinds
}

fn effect_rules() EffectRules {
	val := code.diagram_effect_rules_value() or {
		assert false, 'diagram_effect_rules_value: ${err}'
		return EffectRules{}
	}
	mut t := EffectRules{}
	if val is cx.Element {
		for it in val.items {
			if it is cx.Element {
				mut a := map[string]string{}
				for at in it.attrs {
					a[at.name] = cx.scalar_value_str_public(at.value)
				}
				match it.name {
					'cap' {
						t.caps << a['name'] or { '' }
						t.flags[a['name'] or { '' }] = a['flag'] or { '' }
					}
					'dir' {
						t.dirs[a['directive'] or { '' }] = a['cap'] or { '' }
					}
					'arm' {
						t.arms << [a['carrier'] or { '' }, a['under'] or { '' }]
					}
					'opaque' {
						t.opaqu << a['kind'] or { '' }
					}
					else {}
				}
			}
		}
	}
	return t
}

fn deg_corpus_dir() string {
	return os.real_path(os.join_path(os.dir(@FILE), 'testdata', 'diagram_effect_golden'))
}

// Every rendered byte of the corpus, at every rung, concatenated — the
// coverage clauses' subject.
fn corpus_renders() string {
	dir := deg_corpus_dir()
	mut files := os.ls(dir) or { return '' }
	files.sort()
	mut all := []string{}
	for f in files {
		if !f.ends_with('.golden') {
			continue
		}
		all << os.read_file(os.join_path(dir, f)) or { '' }
	}
	return all.join('\n')
}

fn test_clause_i_roster_is_set_equal_to_the_engine_capability_names() {
	t := effect_rules()
	engine := code.capability_names()
	assert t.caps.len == 9, 'roster rows: ${t.caps}'
	mut missing_in_module := []string{}
	for c in engine {
		if c !in t.caps {
			missing_in_module << c
		}
	}
	mut missing_in_engine := []string{}
	for c in t.caps {
		if c !in engine {
			missing_in_engine << c
		}
	}
	assert missing_in_module.len == 0, 'engine capabilities with no table row: ${missing_in_module}'
	assert missing_in_engine.len == 0, 'table rows naming no engine capability: ${missing_in_engine}'
	// Order is load-bearing: §11.3 pins the capability node order to the
	// roster order, and the goldens are byte-pinned to it.
	assert t.caps == engine, 'roster order must equal capability_names(): ${t.caps} vs ${engine}'
	// Every row must carry the grant flag the CLI actually accepts.
	for c in t.caps {
		assert t.flags[c] == '--allow-${c}', 'capability ${c}: flag ${t.flags[c]}'
	}
}

fn test_clause_ii_dir_rows_are_live_directives_charging_roster_capabilities() {
	t := effect_rules()
	assert t.dirs.len == 5, 'dir rows: ${t.dirs}'
	for d, capname in t.dirs {
		assert cx.is_directive_name(d), 'dir row `${d}` is not a live §4.1 registry directive'
		assert capname in t.caps, 'dir row `${d}` charges `${capname}`, which is not in the roster'
	}
}

// The image tags an arm carrier can wear. A carrier rides EITHER as a
// bareword positional child (`[then …]`, `[case …]`, `[recover-with …]`)
// or as a `cx:`-prefixed labeled slot (`then=`, `else=`), and the walk
// compares the LOCAL name, so one row covers both.
const arm_carrier_tags = ['then', 'else', 'case', 'default', 'yield', 'recover-with']

fn test_clause_iii_arm_rows_name_live_branch_directives() {
	t := effect_rules()
	assert t.arms.len == 8, 'arm rows: ${t.arms}'
	for a in t.arms {
		carrier := a[0]
		under := a[1]
		assert carrier in arm_carrier_tags, 'arm carrier `${carrier}` is not an image arm tag'
		assert cx.is_directive_name(under), 'arm row under `${under}` is not a live §4.1 registry directive'
	}
	// `yield` is an arm ONLY under [?match]; under a for-comprehension it
	// is an iteration body, and conflating them would mark every loop
	// body conditional. The `under` column exists for this.
	mut yield_unders := []string{}
	for a in t.arms {
		if a[0] == 'yield' {
			yield_unders << a[1]
		}
	}
	assert yield_unders == ['match'], 'yield arm rows: ${yield_unders}'
}

fn test_clause_iv_every_opacity_class_is_corpus_exercised() {
	t := effect_rules()
	assert t.opaqu.len == 5, 'opacity rows: ${t.opaqu}'
	rendered := corpus_renders()
	mut unexercised := []string{}
	for k in t.opaqu {
		if !rendered.contains('unk_${k}[/') {
			unexercised << k
		}
	}
	assert unexercised.len == 0, 'opacity classes no corpus source produces: ${unexercised}'
}

fn test_clause_v_every_capability_is_corpus_reached() {
	t := effect_rules()
	rendered := corpus_renders()
	mut unreached := []string{}
	for c in t.caps {
		id := 'cap_' + c.replace('-', '_')
		if !rendered.contains('${id}{{') {
			unreached << c
		}
	}
	assert unreached.len == 0, 'capabilities no corpus source reaches: ${unreached}'
}

// ── clause (vi): spec §12 ↔ the module table, both directions ──────────

struct SpecEffectRules {
mut:
	caps  []string
	dirs  []string
	arms  [][]string
	opaqu []string
}

fn spec_effect_rules() SpecEffectRules {
	spec_path := os.real_path(os.join_path(os.dir(@FILE), '..', '..', 'spec', '03-approved',
		'std-lib', 'diagram.md'))
	text := os.read_file(spec_path) or {
		assert false, 'read ${spec_path}: ${err}'
		return SpecEffectRules{}
	}
	start := text.index('## §12. The sealed effect-rules table') or {
		assert false, '§12 heading not found in std-lib/diagram.md'
		return SpecEffectRules{}
	}
	body := text[start..]
	mut out := SpecEffectRules{}
	roster_at := body.index('**Capability roster**') or { 0 }
	dirs_at := body.index('**Charging directive heads**') or { 0 }
	arms_at := body.index('**Branch-arm carriers**') or { 0 }
	opaq_at := body.index('**Opacity classes**') or { body.len }
	for line in body[roster_at..dirs_at].split('\n') {
		if c := first_code_cell(line) {
			out.caps << c
		}
	}
	for line in body[dirs_at..arms_at].split('\n') {
		if c := first_code_cell(line) {
			out.dirs << strip_directive(c)
		}
	}
	for line in body[arms_at..opaq_at].split('\n') {
		cells := code_cells(line)
		if cells.len >= 2 {
			out.arms << [cells[0], strip_directive(cells[1])]
		}
	}
	// The opacity classes are a prose list of backticked names.
	tail := body[opaq_at..]
	stop := tail.index('###') or { tail.len }
	for c in backticked(tail[..stop]) {
		if c !in out.opaqu {
			out.opaqu << c
		}
	}
	return out
}

// first_code_cell returns the backticked token in a table row's FIRST
// cell, skipping the header and separator rows.
fn first_code_cell(line string) ?string {
	if !line.starts_with('| `') {
		return none
	}
	cell := line[1..].all_before('|')
	toks := backticked(cell)
	if toks.len == 0 {
		return none
	}
	return toks[0]
}

fn code_cells(line string) []string {
	if !line.starts_with('| `') {
		return []
	}
	mut out := []string{}
	for cell in line.trim('|').split('|') {
		toks := backticked(cell)
		if toks.len > 0 {
			out << toks[0]
		}
	}
	return out
}

fn backticked(s string) []string {
	mut out := []string{}
	mut i := 0
	for {
		a := s.index_after('`', i) or { break }
		b := s.index_after('`', a + 1) or { break }
		tok := s[a + 1..b]
		if tok.len > 0 {
			out << tok
		}
		i = b + 1
	}
	return out
}

fn strip_directive(s string) string {
	if s.starts_with('[?') && s.ends_with(']') {
		return s[2..s.len - 1]
	}
	return s
}

fn assert_effect_set_equal(spec []string, module_ []string, what string) {
	mut missing_in_module := []string{}
	for d in spec {
		if d !in module_ {
			missing_in_module << d
		}
	}
	mut missing_in_spec := []string{}
	for d in module_ {
		if d !in spec {
			missing_in_spec << d
		}
	}
	assert missing_in_module.len == 0, '${what}: spec §12 rows with no module row: ${missing_in_module}'
	assert missing_in_spec.len == 0, '${what}: module rows with no spec §12 row: ${missing_in_spec}'
}

fn test_diagram_effect_clause_vi_spec_tables_and_module_table_are_set_equal() {
	spec := spec_effect_rules()
	t := effect_rules()
	assert spec.caps.len == 9, 'spec roster rows: ${spec.caps}'
	assert spec.dirs.len == 5, 'spec dir rows: ${spec.dirs}'
	assert spec.arms.len == 8, 'spec arm rows: ${spec.arms}'
	assert spec.opaqu.len == 5, 'spec opacity classes: ${spec.opaqu}'
	mut module_dirs := []string{}
	for d, _ in t.dirs {
		module_dirs << d
	}
	assert_effect_set_equal(spec.caps, t.caps, 'capability roster')
	assert_effect_set_equal(spec.dirs, module_dirs, 'charging directive heads')
	assert_effect_set_equal(spec.opaqu, t.opaqu, 'opacity classes')
	mut spec_arms := []string{}
	for a in spec.arms {
		spec_arms << '${a[0]}/${a[1]}'
	}
	mut mod_arms := []string{}
	for a in t.arms {
		mod_arms << '${a[0]}/${a[1]}'
	}
	assert_effect_set_equal(spec_arms, mod_arms, 'branch-arm carriers')
}

fn test_clause_vii_the_module_reads_the_engine_map_live() {
	gated := code.capability_gated_prims()
	mut names := gated.keys()
	names.sort()
	mut wrong := []string{}
	for n in names {
		got := code.diagram_effect_cap(n) or {
			wrong << '${n}: ${err}'
			continue
		}
		if got != gated[n] {
			wrong << '${n}: module says `${got}`, engine says `${gated[n]}`'
		}
	}
	assert wrong.len == 0, 'the module is not reading the live engine map: ${wrong}'
	// And a name the engine charges nothing for must come back empty —
	// not guessed.
	empty := code.diagram_effect_cap('concat') or {
		assert false, 'diagram_effect_cap(concat): ${err}'
		return
	}
	assert empty == '', 'concat charges nothing; module said `${empty}`'
}

// ── source: vcx/tests/diagram_effect_golden_test.v ──
// diagram_effect_golden_test.v — the byte gate for the EFFECT/CAPABILITY
// graph (RULED: DGX-1 / DGX-1d,
// ledger/rulings_2026_08_21_diagram_capabilities.md).
//
// The corpus under vcx/tests/testdata/diagram_effect_golden/ is AUTHORED
// rather than captured: this kind never shipped in V, so the DR-8
// capture-then-cut-over instrument the other three corpora used does not
// exist for it. Every byte was read and reviewed at landing, and the
// corpus is frozen from that point under the same rule — regenerating it
// (vcx/tools/regen_diagram_effect_golden) is GOLDEN MOVEMENT, forbidden
// except under a mini-ruling recorded in the ledger BEFORE the bytes
// move.
//
// Each id carries `<id>.source` beside `<id>.<level>.golden`; this
// renderer embeds no source marker (it is in the `code-diagram` family).

fn deg_golden_dir() string {
	return os.real_path(os.join_path(os.dir(@FILE), 'testdata', 'diagram_effect_golden'))
}

fn test_effect_graph_output_matches_the_authored_goldens_bit_for_bit() {
	dir := deg_golden_dir()
	mut files := os.ls(dir) or {
		assert false, 'golden dir missing: ${dir}'
		return
	}
	files.sort()
	mut ran := 0
	mut failures := []string{}
	for f in files {
		if !f.ends_with('.golden') {
			continue
		}
		golden := os.read_file(os.join_path(dir, f)) or {
			failures << '${f}: read: ${err}'
			continue
		}
		stem := f.all_before_last('.golden')
		level := stem.all_after_last('.')
		id := stem.all_before_last('.')
		assert level in ['min', 'compact', 'full'], '${f}: unrecognised level'
		source := os.read_file(os.join_path(dir, '${id}.source')) or {
			failures << '${f}: missing source sidecar ${id}.source: ${err}'
			continue
		}
		rendered := code.effect_graph_with_level(source, code.parse_code_diagram_level(level)) or {
			failures << '${f}: render: ${err}'
			continue
		}
		if rendered != golden {
			failures << '${f}: BYTE DIVERGENCE (rendered ${rendered.len}B vs golden ${golden.len}B)\n--- rendered ---\n${rendered}\n--- golden ---\n${golden}'
		}
		ran++
	}
	if failures.len > 0 {
		println('${failures.len} effect-graph golden failure(s):')
		for fl in failures {
			println('  ${fl}')
		}
	}
	assert failures.len == 0
	assert ran >= 87, 'expected the full 29-source × 3-rung corpus, ran ${ran}'
}

// The CLI and a CX program's own call must produce the same bytes for
// the same source — the same "one path, no twin" property #889 pinned
// for `of-source`. `cx code-diagram --view=effects` reaches
// `effect_graph_with_level`, which is what this asserts against the
// module entry the corpus was captured through.
fn test_effect_graph_default_level_is_compact() {
	src := '[\$io:read-file "/etc/hosts"]'
	via_default := code.effect_graph_with_level(src, code.parse_code_diagram_level('')) or {
		assert false, 'render: ${err}'
		return
	}
	via_compact := code.effect_graph_with_level(src, .compact) or {
		assert false, 'render: ${err}'
		return
	}
	assert via_default == via_compact
}

// DGX-1c is normative and this is its teeth at the OUTPUT level: a
// source carrying an opacity site must never render a graph that omits
// it. Checked here rather than only in the corpus so the property
// survives a corpus edit.
fn test_every_opacity_source_renders_an_unknown_edge() {
	cases := {
		'[?eval \$t]':                             'unk_eval'
		'[\$nosuchmod:go 1]':                      'unk_call'
		'[+ x=1 [\$io:read-file "/y"] 2]':         'unk_dynamic'
		"[?lib './x.cx' as=h]\n[ok]":              'unk_lib'
		'[\$journal:read \$j]':                    'unk_ring2'
	}
	for src, want in cases {
		out := code.effect_graph_with_level(src, .min) or {
			assert false, 'render ${src}: ${err}'
			continue
		}
		assert out.contains(want), 'source ${src} must render ${want}; got:\n${out}'
		assert out.contains('any granted capability'), 'source ${src} must carry the any-capability sink; got:\n${out}'
	}
}

// ── source: vcx/tests/diagram_mermaid_golden_test.v ──
// diagram_mermaid_golden_test.v — the DR-8 bit-for-bit gate (#758,
// RULED DR-1…DR-11 2026-08-20).
//
// The corpus under vcx/tests/testdata/diagram_mermaid_golden/ was
// captured ONCE from the unmodified V reference renderer at the wave-1
// head (vcx/tools/regen_diagram_golden regenerates it — regeneration
// after the cutover is GOLDEN MOVEMENT, forbidden except under a DR-8
// mini-ruling recorded in the ledger BEFORE the bytes move). Every
// golden embeds its own source in the `%%cx:<base64>%%` marker, so the
// gate is self-contained:
//
//   for each *.golden: reverse_parse (mermaid extract) → source;
//   render_diagram(source, `mermaid:<detail-from-name>`) — the lift is internal;
//   assert BYTE EQUALITY with the golden.
//
// This doubles as the extract-mermaid gate: a broken extractor fails
// every file loudly.

fn mermaid_golden_dir() string {
	return os.real_path(os.join_path(os.dir(@FILE), 'testdata', 'diagram_mermaid_golden'))
}

fn test_mermaid_output_matches_captured_goldens_bit_for_bit() {
	dir := mermaid_golden_dir()
	mut files := os.ls(dir) or {
		assert false, 'golden dir missing: ${dir}'
		return
	}
	files.sort()
	mut ran := 0
	mut failures := []string{}
	for f in files {
		if !f.ends_with('.golden') {
			continue
		}
		golden := os.read_file(os.join_path(dir, f)) or {
			failures << '${f}: read: ${err}'
			continue
		}
		// <id>.<detail>.golden
		stem := f.all_before_last('.golden')
		detail := stem.all_after_last('.')
		assert detail in ['min', 'compact', 'full'], '${f}: unrecognised detail rung'
		source := code.reverse_parse_diagram(golden, 'mermaid') or {
			failures << '${f}: extract-mermaid: ${err}'
			continue
		}
		// The embedded source must still PARSE (a broken extractor
		// would otherwise sail past); the render lifts from it itself.
		cx.parse_program(source) or {
			failures << '${f}: parse(embedded source): ${err}'
			continue
		}
		rendered := code.render_diagram(source, 'mermaid:${detail}') or {
			failures << '${f}: render: ${err}'
			continue
		}
		if rendered != golden {
			mut first_diff := -1
			min_len := if rendered.len < golden.len { rendered.len } else { golden.len }
			for i in 0 .. min_len {
				if rendered[i] != golden[i] {
					first_diff = i
					break
				}
			}
			failures << '${f}: BYTE DIVERGENCE at offset ${first_diff} (rendered ${rendered.len}B vs golden ${golden.len}B)\n--- rendered ---\n${rendered}\n--- golden ---\n${golden}'
		}
		ran++
	}
	if failures.len > 0 {
		println('${failures.len} golden failure(s):')
		for fl in failures {
			println('  ${fl}')
		}
	}
	assert failures.len == 0
	assert ran >= 120, 'expected the full 40-source × 3-rung corpus, ran ${ran}'
}

// ── source: vcx/tests/diagram_vector_golden_test.v ──
// diagram_vector_golden_test.v — the WAVE-2 DR-8 bit-for-bit gate
// (#758, RULED 2026-08-20; ledger/rulings_2026_08_20_diagram_renderer.md).
//
// The corpus under vcx/tests/testdata/diagram_vector_golden/ was
// captured from the UNMODIFIED V renderer BEFORE the wave-2 cutover.
// It pins the DETERMINISTIC halves of the SVG/PNG path — the DOT text,
// both dot-less envelopes, and both metadata splices over FIXED inputs
// — so the CX port is byte-checkable without graphviz. graphviz's own
// output is version- and font-dependent and is therefore NOT goldened;
// the live end-to-end hop is gate 9's job.
//
// This lane is hermetic: it never spawns `dot` and needs no
// capability. Regenerating the corpus is golden movement — forbidden
// except under a DR-8 mini-ruling recorded in the ledger first.

const fixed_svg_input = '<?xml version="1.0"?>\n<svg width="10" height="10" xmlns="http://www.w3.org/2000/svg">\n  <g id="graph0"><title>CX</title></g>\n</svg>\n'

// The GRAPHVIZ-SHAPED input (RULED: DSC-1a, #890) — XML declaration,
// then a DOCTYPE, then comments, then the root element: the document
// shape `dot -Tsvg` really emits, and the shape that made the old
// "splice after the first `>`" rule produce a malformed document. The
// short fixed_svg_input above cannot expose the defect on its own
// (it has no DOCTYPE and no comments), so validity is gated over BOTH.
const graphviz_shaped_svg_input = '<?xml version="1.0" encoding="UTF-8" standalone="no"?>\n<!DOCTYPE svg PUBLIC "-//W3C//DTD SVG 1.1//EN"\n "http://www.w3.org/Graphics/SVG/1.1/DTD/svg11.dtd">\n<!-- Generated by graphviz version 14.1.3 (20260303.0454)\n -->\n<!-- Title: CX Pages: 1 -->\n<svg width="98pt" height="332pt"\n viewBox="0.00 0.00 98.00 332.00" xmlns="http://www.w3.org/2000/svg" xmlns:xlink="http://www.w3.org/1999/xlink">\n<g id="graph0" class="graph" transform="scale(1 1) rotate(0) translate(4 328)">\n<title>CX</title>\n</g>\n</svg>\n'

const fixed_source = '[?retry max=3 [?timeout 500ms [?async [?http-client target=\$url]]]]'

fn vector_golden_dir() string {
	return os.real_path(os.join_path(os.dir(@FILE), 'testdata', 'diagram_vector_golden'))
}

fn read_golden(name string) string {
	return os.read_file(os.join_path(vector_golden_dir(), name)) or {
		assert false, 'missing golden ${name}: ${err}'
		return ''
	}
}

fn fixture_path() string {
	return os.real_path(os.join_path(os.dir(@FILE), '..', '..', 'conformance', 'code.cxd'))
}

// (i) the DOT text for every supported viz fixture, byte-for-byte.
fn test_dot_text_matches_pre_cutover_goldens() {
	mut ran := 0
	mut failures := []string{}
	for c in fixtures.load_fixtures(fixture_path()) {
		if !c.name.starts_with('program-viz-') {
			continue
		}
		if (c.sections['out_err'] or { '' }).trim_space() != '' {
			continue
		}
		golden_file := os.join_path(vector_golden_dir(), '${c.name}.dot')
		if !os.exists(golden_file) {
			continue
		}
		expected := os.read_file(golden_file) or {
			failures << '${c.name}: read golden: ${err}'
			continue
		}
		prog := cx.parse_program(c.sections['in_code']) or {
			failures << '${c.name}: parse: ${err}'
			continue
		}
		got := code.render_dot_cx(prog) or {
			failures << '${c.name}: render-dot: ${err}'
			continue
		}
		if got != expected {
			failures << '${c.name}: DOT BYTE DIVERGENCE\n--- got ---\n${got}\n--- golden ---\n${expected}'
		}
		ran++
	}
	if failures.len > 0 {
		println('${failures.len} DOT failure(s):')
		for f in failures {
			println('  ${f}')
		}
	}
	assert failures.len == 0
	assert ran >= 20, 'expected the 20 supported viz fixtures, ran ${ran}'
}

// (ii) the two dot-less envelopes — DR-3a's named normative contract.
fn test_dot_less_envelopes_match_pre_cutover_goldens() {
	svg := code.diagram_svg_envelope_cx(fixed_source) or {
		assert false, 'svg-envelope: ${err}'
		return
	}
	assert svg == read_golden('envelope.svg'), 'SVG envelope byte divergence'
	png := code.diagram_png_envelope_cx(fixed_source) or {
		assert false, 'png-envelope: ${err}'
		return
	}
	assert png == read_golden('envelope.png'), 'PNG envelope byte divergence'
	// The envelope must round-trip through the module's own extractor.
	back := code.reverse_parse_diagram(svg, 'svg') or {
		assert false, 'svg envelope extract: ${err}'
		return
	}
	assert back == fixed_source
	back_png := code.reverse_parse_diagram(png, 'png') or {
		assert false, 'png envelope extract: ${err}'
		return
	}
	assert back_png == fixed_source
}

// (iii) the two splices over fixed inputs — the SVG "first >" rule and
// the PNG IHDR-offset walk + CRC-32, pinned without graphviz.
fn test_metadata_splices_match_pre_cutover_goldens() {
	svg := code.diagram_svg_splice_cx(fixed_svg_input, fixed_source) or {
		assert false, 'svg splice: ${err}'
		return
	}
	assert svg == read_golden('splice.svg'), 'SVG splice byte divergence'
	png_in := code.diagram_png_envelope_cx('') or {
		assert false, 'png input: ${err}'
		return
	}
	png := code.diagram_png_splice_cx(png_in, fixed_source) or {
		assert false, 'png splice: ${err}'
		return
	}
	assert png == read_golden('splice.png'), 'PNG splice byte divergence'
	// Both spliced forms recover the source.
	assert code.reverse_parse_diagram(svg, 'svg')! == fixed_source
	assert code.reverse_parse_diagram(png, 'png')! == fixed_source
}

// ── (v) SVG DOCUMENT VALIDITY — the DSC-1a gate (#890) ──────────────
//
// Before DSC-1a the metadata carrier was spliced after the FIRST `>`
// in the document, which on real graphviz output is the end of the
// `<?xml …?>` declaration. The block therefore landed in the PROLOG,
// and XML 1.0 §2.1 admits neither an element before the doctype
// (`prolog ::= XMLDecl? Misc* (doctypedecl Misc*)?`) nor a second
// top-level element (`document ::= prolog element Misc*`); libxml2
// reported `Extra content at the end of the document` on every SVG
// `cx diagram` ever emitted. The carrier now goes inside the root.
//
// This is a GATE, not a one-time repair: it holds for every emitted
// SVG form, and every one must still recover the source byte-for-byte.
// It is hermetic — the graphviz-shaped input is a fixture, not a spawn.

// svg_document_violation encodes the two XML 1.0 §2.1 clauses the old
// splice broke, plus the SVG 1.1 §5.10 containment the fix relies on.
// Returns '' for a well-formed carrier document, else the violation.
//
// Deliberately NOT `cx.parse_xml`: that reader layers CX document
// policy on top of XML (it refuses a re-bound `cx:` prefix, E213,
// which the carrier's own `xmlns:cx` declaration trips), so it would
// answer a different question than "is this a valid XML document".
//
// Returning the reason rather than asserting inline is what lets the
// NEGATIVE case below prove the check is not vacuous: the pre-DSC-1
// bytes must be REJECTED by this same function.
fn svg_document_violation(svg string) string {
	root := svg.index('<svg') or { return 'no <svg> root element' }
	// (1) The prolog admits only declarations, PIs and comments — every
	//     `<` before the root must open `<?` or `<!`. A stray element
	//     here IS the DRW2-2 defect.
	prolog := svg[..root]
	mut at := 0
	for {
		lt := prolog.index_after('<', at) or { break }
		nxt := if lt + 1 < prolog.len { prolog[lt + 1] } else { u8(0) }
		if nxt != `?` && nxt != `!` {
			return 'element in the prolog at byte ${lt} — XML 1.0 §2.1 admits no element before the root: ${prolog[lt..]}'
		}
		at = lt + 1
	}
	// (2) A doctype, when present, precedes the root element.
	if dt := svg.index('<!DOCTYPE') {
		if dt > root {
			return '<!DOCTYPE> follows the root element'
		}
	}
	// (3) Exactly one root: the document ends at the root close.
	close := svg.last_index('</svg>') or { return 'root element never closed' }
	if svg[close + 6..].trim_space() != '' {
		return 'content after the root element close: ${svg[close + 6..]}'
	}
	// (4) SVG 1.1 §5.10 — the carrier is a CHILD of the root, not a
	//     sibling: it sits between the root start tag and its close.
	carrier := svg.index('<cx:source') or { return 'no <cx:source> carrier' }
	if carrier < root {
		return 'the carrier precedes the root element'
	}
	if carrier > close {
		return 'the carrier follows the root element close'
	}
	if (svg.index('<metadata>') or { -1 }) < root {
		return 'the <metadata> wrapper is outside the root element'
	}
	return ''
}

fn assert_svg_document_wellformed(label string, svg string) {
	v := svg_document_violation(svg)
	assert v == '', '${label}: ${v}'
}

// The NEGATIVE half of the gate: the exact bytes the renderer emitted
// BEFORE DSC-1a — the carrier spliced after the first `>`, i.e. into
// the prolog — must be REJECTED. Without this case a checker that
// silently passed everything would look green forever.
const pre_dsc1_malformed_splice = '<?xml version="1.0"?>\n  <metadata><cx:source xmlns:cx="https://cx.lang/v1">Wz9d</cx:source></metadata>\n<svg width="10" height="10" xmlns="http://www.w3.org/2000/svg">\n  <g id="graph0"><title>CX</title></g>\n</svg>\n'

fn test_the_validity_check_rejects_the_pre_dsc1_form() {
	v := svg_document_violation(pre_dsc1_malformed_splice)
	assert v != '', 'the pre-DSC-1 prolog splice must be REJECTED — the gate is vacuous otherwise'
	assert v.contains('prolog'), 'expected the prolog violation, got: ${v}'
	// …and the fixed emitter must not produce anything like it.
	assert svg_document_violation(code.diagram_svg_splice_cx(fixed_svg_input, fixed_source)!) == ''
}

fn test_every_emitted_svg_form_is_a_wellformed_document() {
	envelope := code.diagram_svg_envelope_cx(fixed_source) or {
		assert false, 'svg-envelope: ${err}'
		return
	}
	splice := code.diagram_svg_splice_cx(fixed_svg_input, fixed_source) or {
		assert false, 'svg splice: ${err}'
		return
	}
	graphviz := code.diagram_svg_splice_cx(graphviz_shaped_svg_input, fixed_source) or {
		assert false, 'graphviz-shaped svg splice: ${err}'
		return
	}
	forms := {
		'dot-less envelope':      envelope
		'splice (fixed input)':   splice
		'splice (graphviz-shaped input)': graphviz
	}
	for label, svg in forms {
		assert_svg_document_wellformed(label, svg)
		// Validity is worthless if the carrier stopped carrying: the
		// gate-9 contract must hold on the fixed form, byte-for-byte.
		back := code.reverse_parse_diagram(svg, 'svg') or {
			assert false, '${label}: extract: ${err}'
			continue
		}
		assert back == fixed_source, '${label}: the recovered source is not byte-identical'
	}
	// The carrier must be spliced ONCE, and the drawing must survive it
	// intact — a splice that ate document bytes would still parse.
	assert graphviz.count('<cx:source') == 1
	assert graphviz.contains('<g id="graph0"'), 'the drawing was damaged by the splice'
	assert graphviz.contains('<!DOCTYPE svg PUBLIC'), 'the doctype was damaged by the splice'
}

// A self-closing root (`<svg …/>`) has no child position; the splice
// opens it into a container so the carrier has somewhere valid to live
// rather than landing outside the document element.
fn test_self_closing_root_is_opened_for_the_carrier() {
	out := code.diagram_svg_splice_cx('<?xml version="1.0"?>\n<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1 1"/>\n',
		fixed_source) or {
		assert false, 'self-closing splice: ${err}'
		return
	}
	assert_svg_document_wellformed('self-closing root', out)
	assert code.reverse_parse_diagram(out, 'svg')! == fixed_source
}

// A `>` inside a quoted attribute value does not end the start tag
// (XML 1.0 `AttValue`), so the carrier must still land after the REAL
// tag end — not in the middle of an attribute.
fn test_quoted_gt_in_the_root_start_tag_does_not_split_it() {
	out := code.diagram_svg_splice_cx('<?xml version="1.0"?>\n<svg xmlns="http://www.w3.org/2000/svg" data-note="a &gt; b > c" viewBox="0 0 1 1">\n  <g/>\n</svg>\n',
		fixed_source) or {
		assert false, 'quoted-gt splice: ${err}'
		return
	}
	assert_svg_document_wellformed('quoted > in the start tag', out)
	assert out.contains('data-note="a &gt; b > c"'), 'the attribute value was split'
	assert code.reverse_parse_diagram(out, 'svg')! == fixed_source
}

// (iv) the PNG CRC-32 in CX agrees with the known RFC vectors — the
// one piece of the port that reimplements an algorithm rather than a
// byte layout, so it is pinned independently of the corpus.
fn test_png_crc32_matches_known_vectors() {
	assert code.diagram_crc32_cx('abc')! == 891568578 // 0x352441C2
	assert code.diagram_crc32_cx('IEND')! == 2923585666 // 0xAE426082
	assert code.diagram_crc32_cx('')! == 0
}

// ── (vi) PNG STRUCTURE — the DSC-1b verdict, pinned (#890) ──────────
//
// The SVG carrier was malformed; the PNG carrier was checked for the
// analogous defect and found CLEAN — `tEXt` is an ancillary chunk that
// RFC 2083 §4.2.3 admits anywhere between IHDR and IEND, and the
// splice puts it right after IHDR with a correct CRC. This case keeps
// that true rather than leaving it a one-time observation.

struct PngChunk {
	ctype  string
	data   []u8
	crc_ok bool
}

fn png_walk(png string) ([]PngChunk, bool) {
	b := png.bytes()
	mut out := []PngChunk{}
	mut pos := 8
	for pos + 12 <= b.len {
		ln := int(u32(b[pos]) << 24 | u32(b[pos + 1]) << 16 | u32(b[pos + 2]) << 8 | u32(b[pos + 3]))
		if ln < 0 || pos + 12 + ln > b.len {
			return out, false // a length that overruns the file
		}
		stored := u32(b[pos + 8 + ln]) << 24 | u32(b[pos + 9 + ln]) << 16 | u32(b[pos + 10 + ln]) << 8 | u32(b[pos + 11 + ln])
		calc := u32(code.diagram_crc32_cx(b[pos + 4..pos + 8 + ln].bytestr()) or { -1 })
		out << PngChunk{
			ctype:  b[pos + 4..pos + 8].bytestr()
			data:   b[pos + 8..pos + 8 + ln].clone()
			crc_ok: stored == calc
		}
		pos += 12 + ln
	}
	return out, pos == b.len // the walk must land exactly on the end
}

fn assert_png_structurally_valid(label string, png string, want_carriers int) {
	assert png.len > 8, '${label}: too short for a signature'
	assert png.bytes()[..8] == [u8(0x89), 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a],
		'${label}: bad PNG signature'
	chunks, exact := png_walk(png)
	assert exact, '${label}: the chunk walk did not land on the end of the file'
	assert chunks.len >= 3, '${label}: ${chunks.len} chunks'
	assert chunks[0].ctype == 'IHDR', '${label}: first chunk is ${chunks[0].ctype}, must be IHDR'
	assert chunks[chunks.len - 1].ctype == 'IEND',
		'${label}: last chunk is ${chunks[chunks.len - 1].ctype}, must be IEND'
	mut carriers := 0
	for c in chunks {
		assert c.crc_ok, '${label}: ${c.ctype} chunk CRC-32 mismatch'
		if c.ctype == 'tEXt' {
			sep := c.data.index(u8(0))
			assert sep > 0, '${label}: tEXt chunk has no keyword separator'
			kw := c.data[..sep].bytestr()
			assert kw == 'cx-source', '${label}: tEXt keyword ${kw}, expected cx-source'
			carriers++
		}
	}
	assert carriers == want_carriers, '${label}: ${carriers} cx-source chunks, expected ${want_carriers}'
}

fn test_png_forms_are_structurally_valid() {
	envelope := code.diagram_png_envelope_cx(fixed_source) or {
		assert false, 'png-envelope: ${err}'
		return
	}
	// The splice's fixed input is the EMPTY-source envelope (case iii's
	// input, kept so both cases describe the same bytes), which already
	// carries one `cx-source` chunk — hence two after the splice. The
	// spliced one lands first (immediately after IHDR), which is why
	// the extractor's first-match walk recovers the real source.
	blank := code.diagram_png_envelope_cx('') or {
		assert false, 'png input: ${err}'
		return
	}
	spliced := code.diagram_png_splice_cx(blank, fixed_source) or {
		assert false, 'png splice: ${err}'
		return
	}
	assert_png_structurally_valid('dot-less envelope', envelope, 1)
	assert_png_structurally_valid('tEXt splice', spliced, 2)
	for label, png in {
		'dot-less envelope': envelope
		'tEXt splice':       spliced
	} {
		back := code.reverse_parse_diagram(png, 'png') or {
			assert false, '${label}: extract: ${err}'
			continue
		}
		assert back == fixed_source, '${label}: the recovered source is not byte-identical'
	}
}

// ── source: vcx/tests/diagram_bench_gate_test.v ──
// diagram_bench_gate_test.v — the DR-6 performance gate (#758, RULED
// 2026-08-20; ledger/rulings_2026_08_20_diagram_renderer.md), rebuilt on
// a load-invariant measure (#893, RULED: ISW-1;
// ledger/rulings_2026_08_21_issue_sweep_893.md).
//
// WHY THIS GATE NO LONGER ASSERTS A WALL TIME.
//
// It used to assert "a 200-node Mermaid render best-of-5 < 25ms". #893
// reported it RED at 55ms; re-measured on a quiet machine the SAME tree
// passes at ~17ms. The 55ms was recorded with five agents compiling in
// parallel. So nothing had regressed — the gate was reporting the load
// average of a shared build box. A gate that goes red because of a
// neighbour's `clang` is worse than a gate that is red: it teaches the
// house to re-run instead of to read.
//
// `parse_amplification_test.v` settled this class for LIM-2 and its
// header is the precedent quoted here: assert a DETERMINISTIC bound,
// PRINT the time as an advisory, never assert it. This gate follows.
//
// WHAT IS ASSERTED (deterministic, load-immune, machine-immune):
//
//   1. LINEARITY of render work in program size. Render at N and 4N
//      nodes and assert
//        steps(4N) <= 4 * steps(N) + slack
//      where `steps` is the F4 evaluation budget's own work counter
//      (eval_node entries, S6.2 — see code.diagram_render_steps). A
//      renderer that starts doing quadratic per-node work goes red here
//      on every machine; a renderer that merely gets 10% heavier does
//      not, and neither does the diagram module growing new kinds. That
//      is the right sensitivity for a tripwire: it catches the ALGORITHM
//      changing shape, which is the only thing a fixed ceiling was ever
//      really guarding, and it needs no recalibration when the module or
//      the machine changes.
//   2. Output linearity — bytes(4N) <= 4 * bytes(N) + slack — so a
//      render that stays cheap in steps while amplifying its output is
//      caught too.
//   3. The render still produces a Mermaid flowchart at both sizes.
//
// WHAT IS PRINTED, NEVER ASSERTED:
//
//   the best-of-5 wall time for the 200-node render, so drift stays
//   visible in the logs. DR-6's 25ms figure and its 12-18ms landing
//   measurement live on in spec/03-approved/std-lib/diagram.md §8 as a
//   CALIBRATION NOTE naming the machine and conditions they were taken
//   under — a recorded measurement, not a pass/fail criterion this gate
//   can honestly own.
//
// Calibration of the slack terms (2026-08-21, this tree, Apple silicon,
// load average ~3, and load-INDEPENDENT by construction): the 99-stage
// render costs 52381 eval steps and the 396-stage render 205336 — ratio
// 3.92 for 4x the stages. Fitting steps = a·stages + b gives a ≈ 515 per
// stage and a FIXED per-render cost b ≈ 1400 steps, which is what the
// slack term exists to cover; 25000 is ~18x that fixed cost, i.e. ~12%
// headroom over the measured 205336 against a 234524 bound. A quadratic
// renderer would need ~838000 at the same size, so the bound separates
// the two by nearly 4x. Both ratios are printed on every run, so a future
// reader sees the real numbers next to the bound instead of trusting this
// comment.

// The linearity bound: work at 4N may be at most 4x the work at N, plus
// a slack term for the fixed per-render cost (module entry, PI strip,
// patches, envelope) that does not scale with the program. Slack is
// deliberately generous — this gate exists to catch a change of SHAPE
// (quadratic), not a change of constant.
const bench_linearity_slack = u64(25_000)

const bench_bytes_slack = 4096

// build_n_node_program builds a pipeline with `stages` [?fn] stages —
// 1 input + `stages` stage nodes + start/result — and per-stage labels,
// i.e. roughly `stages` rendered nodes' worth of per-node dispatch +
// label + emit work.
fn build_n_node_program(stages int) string {
	mut src := '[?pipe (1, 2, 3)'
	for i in 0 .. stages {
		src += ' through=[?fn (\$x) [* \$x ${i}]]'
	}
	src += ']'
	return src
}

fn build_200_node_program() string {
	return build_n_node_program(99)
}

fn test_mermaid_render_work_is_linear_in_program_size() {
	small_src := build_n_node_program(99) // ~200 rendered nodes
	big_src := build_n_node_program(396) // 4x the stages
	cx.parse_program(small_src) or {
		assert false, 'bench program parse (small): ${err}'
		return
	}
	cx.parse_program(big_src) or {
		assert false, 'bench program parse (big): ${err}'
		return
	}
	// Warm-up: loads + caches the module so the fixed module-load cost is
	// not attributed to the small render (it would deflate the ratio).
	_, _ := code.diagram_render_steps(small_src, 'mermaid') or {
		assert false, 'warm-up render: ${err}'
		return
	}
	small_out, small_steps := code.diagram_render_steps(small_src, 'mermaid') or {
		assert false, 'small render: ${err}'
		return
	}
	big_out, big_steps := code.diagram_render_steps(big_src, 'mermaid') or {
		assert false, 'big render: ${err}'
		return
	}
	assert small_out.contains('flowchart TD')
	assert big_out.contains('flowchart TD')
	assert small_steps > 0, 'the step counter must actually count (got 0) — a silent nil budget would make this gate vacuous'

	bound := 4 * small_steps + bench_linearity_slack
	eprintln('diagram-bench: eval steps 99-stage=${small_steps} 396-stage=${big_steps} ratio=${f64(big_steps) / f64(small_steps):.2} bound=${bound}')
	assert big_steps <= bound, 'mermaid render work is superlinear in program size: 4x the stages cost ${big_steps} eval steps against a linear bound of ${bound} (= 4 * ${small_steps} + ${bench_linearity_slack})'

	byte_bound := 4 * small_out.len + bench_bytes_slack
	eprintln('diagram-bench: output bytes 99-stage=${small_out.len} 396-stage=${big_out.len} ratio=${f64(big_out.len) / f64(small_out.len):.2} bound=${byte_bound}')
	assert big_out.len <= byte_bound, 'mermaid output amplifies: 4x the stages emitted ${big_out.len} bytes against a linear bound of ${byte_bound}'
}

// The wall-time ADVISORY. Never asserted — see the header. It runs the
// same best-of-5 the old gate ran so the number in the logs stays
// comparable with the DR-6 landing measurement, and it prints the DR-6
// budget alongside so a reader can see the headroom without the build
// machine's load average getting a vote on the exit code.
fn test_mermaid_render_wall_time_advisory() {
	src := build_200_node_program()
	_ := code.render_diagram(src, 'mermaid') or {
		assert false, 'warm-up render: ${err}'
		return
	}
	mut samples := []i64{}
	for _ in 0 .. 5 {
		sw := time.new_stopwatch()
		out := code.render_diagram(src, 'mermaid') or {
			assert false, 'render: ${err}'
			return
		}
		samples << sw.elapsed().microseconds()
		assert out.contains('flowchart TD')
	}
	samples.sort()
	best := samples[0]
	median := samples[2]
	worst := samples[4]
	verdict := if best < 25_000 { 'within' } else { 'OVER' }
	// best / median / worst are all printed on purpose: the SPREAD is the
	// evidence for why this is an advisory. Measured 2026-08-21 on this
	// tree, the eval-step counts above are bit-identical between a quiet
	// machine (load ~3) and one carrying five parallel V+clang compiles
	// (load ~51) — while the wall-time spread widens with load. Timing
	// belongs in the log; the exit code belongs to the linearity bound.
	eprintln('diagram-bench: 200-node mermaid render of 5 — best=${best}µs median=${median}µs worst=${worst}µs (best is ${verdict} the DR-6 calibration figure of 25000µs — ADVISORY, not asserted: these are properties of the machine and its load, not of the renderer; the asserted property is linearity, above)')
}

// ── source: vcx/tests/diagram_of_source_test.v ──
// diagram_of_source_test.v — the #889 byte-identity pin for the
// caller-facing entry (RULED DRW3-1 deliverable B;
// ledger/rulings_2026_08_20_diagram_wave3.md).
//
// The owner's requirement: `[$diagram:of-source $src $format]` "must
// produce byte-identical output to the CLI path for the same input
// (pin it), and the CLI should route through it rather than keeping a
// second lift — one path, no twin."
//
// This pins BOTH halves:
//
//   * the CLI path — `render_diagram(src, fmt)`, which is what
//     `cx diagram` and `cx eval --target=…` reach through
//     `code.eval_code` — and
//   * a CX PROGRAM's own call, evaluated end-to-end through the
//     engine: `[?lib 'cx-stdlib/diagram'] [$diagram:of-source …]`.
//
// The program hands its render back base64-encoded so the comparison
// is over BYTES, not over the value renderer's quoting/escaping.

const of_source_pins = [
	'[greet]',
	'[?if [> \$x 0] [then [pos]] [else [neg]]]',
	'[?for [in \$u //users/user] [yield \$u]]',
	'[?pipe (1, 2) through=[?fn (\$x) [* \$x 2]]]',
	'[user id=1 name=\'ada\']',
]

fn render_via_cx_program(src string, format string, detail string) !string {
	prog := "[?lib 'cx-stdlib/diagram' as=diagram]\n" +
		"[?lib 'cx-stdlib/bytes' as=bytes]\n" +
		'[$bytes:to-base64 [$bytes:from-string-utf8 [$diagram:of-source ${cx_string_literal(src)} "${format}" detail="${detail}"]]]'
	out := code.eval_code('', prog, 'text')!
	// A string result renders quoted; base64 carries no quote bytes.
	trimmed := out.trim_space().trim("'")
	return base64.decode_str(trimmed)
}

// cx_string_literal quotes a CX source string for embedding in a CX
// program: double quotes, backslash-escaped.
fn cx_string_literal(s string) string {
	return '"' + s.replace('\\', '\\\\').replace('"', '\\"').replace('\n', '\\n') + '"'
}

fn test_of_source_matches_the_cli_render_byte_for_byte() {
	mut failures := []string{}
	for src in of_source_pins {
		// The CLI path (cmd/diagram.v → eval_code → render_diagram),
		// which routes THROUGH of-source since #889. `mermaid` with no
		// detail suffix is the DR-11 `min` rung — the same default
		// `of-source` carries. (`dot` is not a CLI target: `cx diagram`
		// takes mermaid|svg|png, so the DOT comparison below is against
		// the module's own image path instead.)
		cli := code.render_diagram(src, 'mermaid') or {
			failures << 'render_diagram(mermaid) on ${src}: ${err}'
			continue
		}
		via := render_via_cx_program(src, 'mermaid', 'min') or {
			failures << 'of-source(mermaid) on ${src}: ${err}'
			continue
		}
		if cli != via {
			failures << 'BYTE DIVERGENCE mermaid on ${src}\n--- cli ---\n${cli}\n--- of-source ---\n${via}'
		}
		// DOT: of-source's internal lift must agree with the seam's
		// image path byte-for-byte (the vector goldens pin that path).
		prog := cx.parse_program(src) or {
			failures << 'parse ${src}: ${err}'
			continue
		}
		seam_dot := code.render_dot_cx(prog) or {
			failures << 'render_dot_cx on ${src}: ${err}'
			continue
		}
		via_dot := render_via_cx_program(src, 'dot', 'min') or {
			failures << 'of-source(dot) on ${src}: ${err}'
			continue
		}
		if seam_dot != via_dot {
			failures << 'BYTE DIVERGENCE dot on ${src}\n--- seam ---\n${seam_dot}\n--- of-source ---\n${via_dot}'
		}
	}
	if failures.len > 0 {
		for f in failures {
			println(f)
		}
	}
	assert failures.len == 0
}

fn test_of_source_detail_rungs_reach_the_same_bytes_as_the_format_suffix() {
	src := '[?pipe (1, 2) through=[?fn (\$x) [* \$x 2]]]'
	for detail in ['min', 'compact', 'full'] {
		cli := code.render_diagram(src, 'mermaid:${detail}') or {
			assert false, 'render_diagram(mermaid:${detail}): ${err}'
			return
		}
		via := render_via_cx_program(src, 'mermaid', detail) or {
			assert false, 'of-source(mermaid, ${detail}): ${err}'
			return
		}
		assert cli == via, 'detail rung ${detail} diverged:\n--- cli ---\n${cli}\n--- of-source ---\n${via}'
	}
}

// RULED: D910-1 (#910) — the ingress's guarded DATA fallback. A pure-data
// document the PROGRAM reading refuses (but the DATA reading accepts, with
// no registered directive) lifts as data, so `cx diagram` and the
// code-diagram ERD lane render it instead of a token-level error / the
// empty placeholder. The source below carries the data-only idioms that
// made the shipped examples/config.cx undiagrammable: a bare URL and a
// bare filesystem path in prose bodies. (The third original idiom, the
// SPACED `::T` annotation, was retired by RULED: TA-1 #911 — it now
// refuses loudly in BOTH readings, so it can no longer carry a fallback.)
fn test_data_document_takes_the_ingress_fallback() {
	src := '[server host=0.0.0.0
  [origins https://example.com]
  [file /var/log/app.log]]'
	// The program reading refuses it (the deliberate reader difference)…
	if _ := cx.parse_program(src) {
		assert false, 'expected the program reading to refuse the data-idiom source'
	}
	// …and the diagram render now succeeds via the data lift.
	out := code.render_diagram(src, 'mermaid') or {
		assert false, 'D910-1 fallback did not render: ${err.msg()}'
		return
	}
	assert out.starts_with('%%cx:'), 'embed-source metadata missing'
	assert out.contains('flowchart TD'), 'expected a flowchart render, got: ${out}'
	// eval_code's diagram arm (the `cx diagram` CLI path) reaches the
	// same bytes — one lift path, no twin.
	cli := code.eval_code('', src, 'mermaid') or {
		assert false, 'eval_code mermaid on a data doc: ${err.msg()}'
		return
	}
	assert cli == out, 'CLI path diverged from render_diagram'
	// The code-diagram ERD lane is no longer the EMPTY placeholder.
	erd := code.code_diagram(src) or {
		assert false, 'code-diagram on a data doc: ${err.msg()}'
		return
	}
	assert erd.contains('server {'), 'expected a populated erDiagram, got: ${erd}'
}

fn test_d910_fallback_guards_keep_program_intent_fail_loud() {
	// A source BOTH readings refuse keeps the verbatim ingress [err].
	if _ := code.render_diagram('[?if [ unbalanced', 'mermaid') {
		assert false, 'expected refusal for a source both readings refuse'
	}
	// A broken source whose DATA reading carries a registered
	// [?directive] is unambiguous PROGRAM intent — no fallback (the
	// eval_code guard, shared by the ingress).
	if _ := code.render_diagram('[?modify $doc [set count 1] [append item]]', 'mermaid') {
		assert false, 'expected refusal for a program-shaped source'
	}
}

// RULED: DGF-1 (#912) — eval_code (the `cx diagram` CLI path) matches
// diagram targets on the BASE format and passes the FULL string through to
// render_diagram, which owns the detail suffix (parse_diagram_format). The
// rungs the layer below already implements (of-source, the wasm export, the
// gates) now reach the CLI. One pin per rung, on the program arm AND the
// D910-1 data-fallback arm.
fn test_dgf1_cli_path_takes_the_detail_rungs() {
	src := '[user name=alice role=admin tenant=acme]'
	for rung in ['mermaid', 'mermaid:min', 'mermaid:compact', 'mermaid:full'] {
		want := code.render_diagram(src, rung) or {
			assert false, 'render_diagram(${rung}): ${err.msg()}'
			return
		}
		got := code.eval_code('', src, rung) or {
			assert false, 'eval_code(${rung}): ${err.msg()}'
			return
		}
		assert got == want, 'CLI path diverged from render_diagram on ${rung}'
	}
	// The suffix genuinely reaches the detail engine — the full rung carries
	// the attrs the min rung omits.
	minr := code.eval_code('', src, 'mermaid') or {
		assert false, 'eval_code(mermaid): ${err.msg()}'
		return
	}
	full := code.eval_code('', src, 'mermaid:full') or {
		assert false, 'eval_code(mermaid:full): ${err.msg()}'
		return
	}
	assert full != minr, 'the :full suffix did not change the render'
	assert full.contains('tenant'), 'expected the full rung to carry attrs'
}

fn test_dgf1_data_fallback_arm_takes_the_detail_rungs() {
	// A pure-data source the PROGRAM reading refuses (bare URL + bare path,
	// the D910-1 idioms — deliberately NOT the spaced ::T, which is TA-1's
	// migration target) renders the suffixed rung through the same fallback.
	src := '[server [origins https://example.com] [file /var/log/app.log]]'
	if _ := cx.parse_program(src) {
		assert false, 'expected the program reading to refuse the data-idiom source'
	}
	want := code.render_diagram(src, 'mermaid:full') or {
		assert false, 'render_diagram fallback (mermaid:full): ${err.msg()}'
		return
	}
	got := code.eval_code('', src, 'mermaid:full') or {
		assert false, 'eval_code fallback (mermaid:full): ${err.msg()}'
		return
	}
	assert got == want, 'fallback arm diverged from render_diagram on mermaid:full'
}

// RULED: D913-1 (#913) — a document with NO program structure renders its
// ELEMENT TREE in every format: elements as nodes on the min|compact|full
// label ladder, containment as edges. Before this the DOT walk emitted ZERO
// nodes for such documents (an 8pt empty canvas from `cx diagram
// --format=svg`, exit 0 — the #910 silent-degradation class one lane over)
// and the flowchart collapsed the whole document to the start→…→result
// envelope. Directive renders stay byte-identical (the golden lanes pin it).
fn test_d913_data_doc_renders_its_element_tree() {
	src := '[server host=0.0.0.0
  [origins https://example.com]
  [file /var/log/app.log]]'
	mm := code.render_diagram(src, 'mermaid') or {
		assert false, 'mermaid tree render: ${err.msg()}'
		return
	}
	assert mm.contains('n1["[server'), 'expected the root element node, got: ${mm}'
	assert mm.contains('n1 --> n2'), 'expected a containment edge, got: ${mm}'
	assert !mm.contains('(["start"])'), 'a data doc must not render the program envelope: ${mm}'
	assert !mm.contains('["…"]'), 'the collapsed ellipsis leaf must be gone: ${mm}'
	// The DOT text (the svg/png stdin) carries the same tree.
	dot := render_via_cx_program(src, 'dot', 'min') or {
		assert false, 'of-source dot: ${err.msg()}'
		return
	}
	assert dot.contains('digraph CX {'), 'dot header: ${dot}'
	assert dot.contains('n1 [label="[server'), 'expected the root DOT node, got: ${dot}'
	assert dot.contains('n1 -> n2;'), 'expected a containment edge, got: ${dot}'
	// The detail rung reaches the DOT text (DGF-1 plumbing + D913-1 labels).
	full := render_via_cx_program(src, 'dot', 'full') or {
		assert false, 'of-source dot full: ${err.msg()}'
		return
	}
	assert full.contains('@host='), 'expected attr chips on the full DOT rung, got: ${full}'
}

fn test_d913_multi_form_program_renders_its_forms() {
	// cx:block descends in BOTH walks: a multi-form program renders its
	// chained forms instead of one `…` leaf (mermaid) / an empty canvas
	// (dot). The single-form goldens pin that nothing else moved.
	src := '[?let [= \$x 1] \$x]\n[?let [= \$y 2] \$y]'
	dot := render_via_cx_program(src, 'dot', 'min') or {
		assert false, 'of-source dot multi-form: ${err.msg()}'
		return
	}
	assert dot.contains('[label="[?let]"];'), 'expected directive nodes in the DOT text, got: ${dot}'
	mm := code.render_diagram(src, 'mermaid') or {
		assert false, 'mermaid multi-form: ${err.msg()}'
		return
	}
	assert !mm.contains('n3["…"]'), 'the collapsed block leaf must be gone: ${mm}'
}

fn test_of_source_refuses_an_unknown_format() {
	// Through the CLI surface (render_diagram's own format check) …
	if _ := code.render_diagram('[greet]', 'gif') {
		assert false, 'expected a refusal for an unknown format'
	} else {
		assert err.msg().contains('not recognised'), 'unexpected message: ${err.msg()}'
	}
	// … and through the module entry a CX program calls.
	out := code.eval_code('', "[?lib 'cx-stdlib/diagram' as=diagram]\n[\$diagram:of-source \"[greet]\" \"gif\"]",
		'text') or {
		assert false, 'of-source gif: ${err}'
		return
	}
	assert out.contains('CXER0100'), 'expected a CXER0100 err value, got: ${out}'
	assert out.contains('not recognised'), 'expected the format refusal, got: ${out}'
}

// ── source: vcx/tests/examples_diagram_gate_test.v ──
// examples_diagram_gate_test.v — the EXAMPLES-DIAGRAM GATE.
//
// RULED: EDL-1 / EDL-1a (#913 addendum + the #910 lane suggestion, homed;
// ledger/rulings_2026_08_21_diagram_vector_data.md): every shipped
// `examples/*.cx` (and `examples/comparisons/*.cx`) diagrams with CONTENT,
// not exit codes. Exit-code sweeps measurably lie here — the #913 blanks
// (an 8pt empty svg canvas for every data example) all exited 0, and both
// #910 (the empty erDiagram placeholder) and #913 would have been caught
// at a release by these assertions.
//
// HERMETIC: the mermaid assertion runs `render_diagram` and the vector
// assertion runs `[$diagram:of-source … "dot"]` — the exact DOT text the
// svg/png hop feeds graphviz — never the graphviz subprocess, so the gate
// needs no `dot` installed.
//
// Assertions per example (the ruled content bar):
//   * mermaid renders, carries at least one node line and one edge, and is
//     never the collapsed single-`…`-leaf shape (#913's flowchart symptom);
//   * the DOT text declares at least one node (#913's empty-canvas symptom);
//   * a doc whose code-diagram classification is the ERD is POPULATED —
//     never the bare `erDiagram` placeholder (#910's symptom).
//
// ZERO exclusions. #914 (the TI-1 table image) landed, so table-carrying
// docs render like every other example and the EDL-1a carve-out that named
// them is GONE. Per TI-1 point 5 this gate, green over the FULL corpus with
// no exclusions, IS that issue's completion criterion — so the gate asserts
// it directly (`ran == files.len`) and keeps no skip path that could drift.

fn examples_dir() string {
	return os.real_path(os.join_path(os.dir(@FILE), '..', '..', 'examples'))
}

fn gate_cx_string_literal(s string) string {
	return '"' + s.replace('\\', '\\\\').replace('"', '\\"').replace('\n', '\\n') + '"'
}

// gate_render_dot — the of-source DOT text through the engine, base64-clad
// so the comparison is over bytes (the diagram_of_source_test pattern).
fn gate_render_dot(src string) !string {
	prog := "[?lib 'cx-stdlib/diagram' as=diagram]\n" +
		"[?lib 'cx-stdlib/bytes' as=bytes]\n" +
		'[\$bytes:to-base64 [\$bytes:from-string-utf8 [\$diagram:of-source ${gate_cx_string_literal(src)} "dot" detail="min"]]]'
	out := code.eval_code('', prog, 'text')!
	trimmed := out.trim_space().trim("'")
	return base64.decode_str(trimmed)
}

fn gate_example_files() []string {
	mut files := []string{}
	dir := examples_dir()
	for f in os.ls(dir) or { [] } {
		if f.ends_with('.cx') {
			files << f
		}
	}
	for f in os.ls(os.join_path(dir, 'comparisons')) or { [] } {
		if f.ends_with('.cx') {
			files << os.join_path('comparisons', f)
		}
	}
	files.sort()
	return files
}

fn test_every_shipped_example_diagrams_with_content() {
	files := gate_example_files()
	assert files.len >= 20, 'expected the shipped example corpus, found ${files.len} files'
	mut failures := []string{}
	mut ran := 0
	for rel in files {
		src := os.read_file(os.join_path(examples_dir(), rel)) or {
			failures << '${rel}: read: ${err}'
			continue
		}
		// ── mermaid: renders, with nodes and edges, never the collapse ──
		mm := code.render_diagram(src, 'mermaid') or {
			failures << '${rel}: mermaid render refused: ${err.msg()}'
			continue
		}
		if mm.contains('["…"]') {
			failures << '${rel}: mermaid collapsed to an ellipsis leaf (the #913 flowchart symptom)'
		}
		if !mm.contains('["') {
			// At least one node line. NOT an edge assertion: a flat document
			// of childless elements (logs.cx logfmt lines, books.cx's shelf)
			// legitimately renders nodes with no containment edges.
			failures << '${rel}: mermaid render carries no node'
		}
		// ── the DOT text (the svg/png stdin): at least one declared node ──
		dot := gate_render_dot(src) or {
			failures << '${rel}: of-source dot refused: ${err.msg()}'
			continue
		}
		if !dot.contains(' [label=') {
			failures << '${rel}: DOT text declares no node (the #913 empty-canvas symptom)'
		}
		// ── the ERD lane: when a doc classifies as ERD it must be populated ──
		erd := code.code_diagram(src) or {
			failures << '${rel}: code-diagram refused: ${err.msg()}'
			continue
		}
		if erd.contains('erDiagram') && erd.trim_space() == 'erDiagram' {
			failures << '${rel}: empty erDiagram placeholder (the #910 symptom)'
		}
		ran++
	}
	if failures.len > 0 {
		println('${failures.len} examples-diagram gate failure(s):')
		for f in failures {
			println('  ${f}')
		}
	}
	assert failures.len == 0
	// RULED: TI-1 point 5 — the FULL corpus, no exclusions. Equality, not a
	// floor: a re-introduced skip path fails HERE rather than silently
	// shrinking what the gate covers.
	assert ran == files.len, 'expected the full corpus asserted, ran ${ran} of ${files.len}'
}

// ── #1038: a COMPUTED-name element is STRUCTURE in the image ────────────────
//
// `[?element NAME-EXPR …]` used to reach the renderer as ONE `<cx:expr>`
// source string, because `dgi_element` hatches the whole construct the moment
// `name_expr` is set. Only the NAME is dynamic; the attributes and the body
// are ordinary structure, and hatching them with it cost #1031's §9.4b tables
// everything they could have drawn — the same document under a LITERAL head
// tabled, under a computed head drew a flat line. `dgc_element_image` lifts it
// in the code/effects modes to the shape code.md §6.4.2.2 already rules and
// the E1 quote-image already builds.

const c1038_src = '[?for [in \$i \$doc//item] [yield [?element \$i/@name qty=\$i/@qty [note x]]]]'

fn c1038_image(src string, mode string) string {
	prog := "[\$diagram-program-image '${src}' '${mode}']"
	return code.eval_code('', prog, 'cx') or {
		assert false, 'image(${mode}): ${err.msg()}'
		''
	}
}

// (a) the code image carries the contracted `<cx:element>` / `<cx:name>`
// envelope, the attribute as `cx:attr`, and the body child as itself.
fn test_1038_computed_name_element_images_structurally() {
	img := c1038_image(c1038_src, 'code')
	assert img.contains('[cx:element'), 'the code image must carry cx:element: ${img}'
	assert img.contains('[cx:name'), 'the computed head must ride the cx:name envelope: ${img}'
	assert img.contains('[cx:attr name=qty'), 'the attribute must be a cx:attr child: ${img}'
	assert img.contains('[note'), 'the body child must survive as itself: ${img}'
	// And the whole construct is no longer one opaque string. `$i/@name` is a
	// BINDING with a step in program position, so nothing here is genuinely
	// unstructurable and no hatch is left at all.
	assert !img.contains('?element'), 'no source text may remain: ${img}'
	assert !img.contains('cx:expr'), 'nothing in this shape is opaque: ${img}'
}

// (b) `ref` is the wave-1/2 reference image and is UNTOUCHED — the lift runs
// only in `dgc_expand_defs`. This is what keeps every wave-1/2 golden still.
fn test_1038_ref_image_keeps_the_source_hatch() {
	img := c1038_image(c1038_src, 'ref')
	assert img.contains('cx:expr'), 'ref must still hatch: ${img}'
	assert img.contains('?element'), 'ref must still carry the source text: ${img}'
	assert !img.contains('[cx:element'), 'ref must NOT lift: ${img}'
}

// (c) the deliberate hatch that STAYS in code mode: a PS-1 result step run
// (`[?element …]/x`). The steps live in `lit.path` and this projection has no
// cell for them, so lifting would silently DROP them. The hatch's source text
// carries them, so the hatch is the honest answer.
fn test_1038_stepped_computed_element_keeps_the_hatch() {
	img := c1038_image('[?element \$n a=1]/x', 'code')
	assert img.contains('cx:expr'), 'a stepped literal must keep the hatch: ${img}'
	assert !img.contains('[cx:element'), 'a stepped literal must not lift: ${img}'
}

// (d) the CONSUMER oracle — #1031's §9.4b tables now table it. The computed
// name is the table HEADER (`cd-computed-name`), the attribute is an `@qty`
// row and the leaf child is a `note` row. Before the lift this node's label
// was the verbatim source line.
fn test_1038_computed_name_element_tables_in_the_cfg() {
	for rung in ['compact', 'full'] {
		got := code.code_diagram_with_level(c1038_src, code.parse_code_diagram_level(rung)) or {
			assert false, 'render(${rung}): ${err.msg()}'
			return
		}
		assert got.contains("<table class='cxp-itbl cxp-vtbl'>"),
			'${rung}: the yielded element must draw a table: ${got}'
		assert got.contains("<th colspan='2'>\$i@name</th>"),
			'${rung}: the computed name must be the header: ${got}'
		assert got.contains("<td class='cxp-itbl-k'>@qty</td>"),
			'${rung}: the attribute must be a row: ${got}'
		assert got.contains("<td class='cxp-itbl-k'>note</td>"),
			'${rung}: the leaf child must be a row: ${got}'
		// The `cx:name` envelope is the HEAD, never a row of its own.
		assert !got.contains('cx:name'), '${rung}: the name envelope must not be drawn: ${got}'
		// And the flat source line the issue reports is gone. (The
		// `[?element …]` HEAD spelling survives in `cd-computed-element-label`
		// for a node that does NOT table — a bare `[$n …]` would be the
		// spelling of a call — so this asserts the SOURCE line specifically,
		// not the head token.)
		assert !got.contains('[?element \$i@name qty=\$i@qty'),
			'${rung}: the opaque source label must be gone: ${got}'
	}
	// `min` is untouched at every level (the §9.4b section note) — it emits one
	// box per top-level def and never reaches a value label.
	minr := code.code_diagram_with_level(c1038_src, code.parse_code_diagram_level('min')) or {
		assert false, 'render(min): ${err.msg()}'
		return
	}
	assert !minr.contains('cxp-itbl'), 'min must draw no table: ${minr}'
}

// (e) the two heads that have NOTHING to table, measured because both were
// wrong on the first cut. A bare `[?element \$n]` must keep its `[?element]`
// head — `[\$n]` alone is the spelling of a CALL — and `[?element ()]`, the
// §6.4.2.1 ABSENCE channel, must spell `()`: `[\$exists]` on the empty
// `<cx:seq>` name reads FALSE (the §2 `lab` trap) and `cd-label` answers
// `<lit>` for every sequence, so the naive readings degraded this head to `?`
// and then to `<lit>`, both of which hide that the name is absent.
fn test_1038_headless_computed_elements_stay_legible() {
	src := '[?let [= \$a [?element \$n]] [?let [= \$b [?element ()]] (\$a, \$b)]]'
	got := code.code_diagram_with_level(src, code.parse_code_diagram_level('full')) or {
		assert false, 'render: ${err.msg()}'
		return
	}
	assert got.contains('[?element \$n]'), 'a bare computed head keeps [?element]: ${got}'
	assert got.contains('[?element ()]'), 'the absence channel spells (): ${got}'
	assert !got.contains('[?element ?]'), 'the head must never degrade to ?: ${got}'
	assert !got.contains('[?element <lit>]'), 'the head must never degrade to <lit>: ${got}'
}

// (f) a NESTED computed element is keyed by its own computed name, not by the
// `element` tag — otherwise every `[?element]` row in a document reads
// identically and the table is worse than the line it replaced. Both rungs:
// `full` opens it as an inner table, `compact` summarises it in place.
fn test_1038_nested_computed_element_is_keyed_by_its_name() {
	src := '[?let [= \$d [?element \$top a=1 [?element \$mid b=2 [leaf c=3]]]] \$d]'
	for rung in ['compact', 'full'] {
		got := code.code_diagram_with_level(src, code.parse_code_diagram_level(rung)) or {
			assert false, 'render(${rung}): ${err.msg()}'
			return
		}
		assert got.contains("<th colspan='2'>\$d = \$top</th>"),
			'${rung}: the binding + computed head: ${got}'
		assert got.contains("<td class='cxp-itbl-k'>\$mid</td>"),
			'${rung}: the nested computed element keys by its NAME: ${got}'
		assert !got.contains("<td class='cxp-itbl-k'>element</td>"),
			'${rung}: the image tag must never be a row key: ${got}'
	}
}
